INSERT INTO public.sp_credential_definition_reviews VALUES
('INTL_ACAMS_CAMS','financial_crime','https://www.acams.org/en/certifications/cams-certification','2026-09-16','Treårig omcertifiering, fortbildning och medlemskap enligt ACAMS. Kontrollera aktuell status separat.','CAMS is maintained on a three-year recertification cycle with recertification credits earned within it. No official public holder-verification lookup was confirmed on review, so none is recorded.'),
('INTL_ACFE_CFE','investigation','https://www.acfe.com/cfe-credential','2026-09-16','Årlig fortbildning och aktuellt medlemskap krävs enligt ACFE. Ett utbildningsdatum bevisar inte aktuell status.','The CFE credential is maintained by an ANNUAL continuing-education compliance obligation, not by a fixed multi-year expiry. The ACFE''s Find a CFE directory is opt-in: absence from it is not evidence that a credential is invalid.'),
('INTL_ASIS_APP','security_management','https://www.asisonline.org/certification/associate-protection-professional-app/','2026-09-16','Treårig omcertifiering med fortbildning enligt ASIS. Bevisets aktuella status måste kontrolleras separat.','ASIS board certifications are maintained on a three-year recertification cycle, with continuing professional education recorded through the issuer''s own portal. The cycle is the programme''s; it is not this holder''s expiry date.'),
('INTL_ASIS_CPP','security_management','https://www.asisonline.org/certification/certified-protection-professional-cpp/','2026-09-16','Treårig omcertifiering med fortbildning enligt ASIS. Bevisets aktuella status måste kontrolleras separat.','ASIS board certifications are maintained on a three-year recertification cycle, with continuing professional education recorded through the issuer''s own portal. The cycle is the programme''s; it is not this holder''s expiry date.'),
('INTL_ASIS_PCI','investigation','https://www.asisonline.org/certification/professional-certified-investigator-pci/','2026-09-16','Treårig omcertifiering med fortbildning enligt ASIS. Bevisets aktuella status måste kontrolleras separat.','ASIS board certifications are maintained on a three-year recertification cycle, with continuing professional education recorded through the issuer''s own portal. The cycle is the programme''s; it is not this holder''s expiry date.'),
('INTL_ASIS_PSP','physical_security','https://www.asisonline.org/certification/physical-security-professional/','2026-09-16','Treårig omcertifiering med fortbildning enligt ASIS. Bevisets aktuella status måste kontrolleras separat.','ASIS board certifications are maintained on a three-year recertification cycle, with continuing professional education recorded through the issuer''s own portal. The cycle is the programme''s; it is not this holder''s expiry date.'),
('INTL_ISACA_CISA','information_security','https://www.isaca.org/credentialing/cisa','2026-09-16','Årliga krav och treårig fortbildningscykel enligt ISACA. Kontrollera aktuell status separat.','ISACA certifications carry an annual CPE minimum and an annual maintenance fee, alongside 120 CPE hours across a three-year reporting period. Annual standing can end BEFORE the three-year date printed on the certificate, so the printed date is not current standing.'),
('INTL_ISACA_CISM','information_security','https://www.isaca.org/credentialing/cism','2026-09-16','Årliga krav och treårig fortbildningscykel enligt ISACA. Kontrollera aktuell status separat.','ISACA certifications carry an annual CPE minimum and an annual maintenance fee, alongside 120 CPE hours across a three-year reporting period. Annual standing can end BEFORE the three-year date printed on the certificate, so the printed date is not current standing.'),
('INTL_ISACA_CRISC','information_security','https://www.isaca.org/credentialing/crisc','2026-09-16','Årliga krav och treårig fortbildningscykel enligt ISACA. Kontrollera aktuell status separat.','ISACA certifications carry an annual CPE minimum and an annual maintenance fee, alongside 120 CPE hours across a three-year reporting period. Annual standing can end BEFORE the three-year date printed on the certificate, so the printed date is not current standing.'),
('INTL_ISC2_CC','information_security','https://www.isc2.org/certifications/cc','2026-09-16','Treårig certifieringscykel med fortbildning och avgifter enligt ISC2. Ett cykeldatum bevisar inte aktuell status.','ISC2 certifications run on a three-year cycle AND carry a separate annual maintenance obligation. Both must be in good standing; either alone says nothing about the holder''s current status. CPE totals are credential-specific.'),
('INTL_ISC2_CCSP','information_security','https://www.isc2.org/certifications/ccsp','2026-09-16','Treårig certifieringscykel med fortbildning och avgifter enligt ISC2. Ett cykeldatum bevisar inte aktuell status.','ISC2 certifications run on a three-year cycle AND carry a separate annual maintenance obligation. Both must be in good standing; either alone says nothing about the holder''s current status. CPE totals are credential-specific.'),
('INTL_ISC2_CGRC','information_security','https://www.isc2.org/certifications/cgrc','2026-09-16','Treårig certifieringscykel med fortbildning och avgifter enligt ISC2. Ett cykeldatum bevisar inte aktuell status.','ISC2 certifications run on a three-year cycle AND carry a separate annual maintenance obligation. Both must be in good standing; either alone says nothing about the holder''s current status. CPE totals are credential-specific.'),
('INTL_ISC2_CISSP','information_security','https://www.isc2.org/certifications/cissp','2026-09-16','Treårig certifieringscykel med fortbildning och avgifter enligt ISC2. Ett cykeldatum bevisar inte aktuell status.','ISC2 certifications run on a three-year cycle AND carry a separate annual maintenance obligation. Both must be in good standing; either alone says nothing about the holder''s current status. CPE totals are credential-specific.'),
('INTL_ISC2_SSCP','information_security','https://www.isc2.org/certifications/sscp','2026-09-16','Treårig certifieringscykel med fortbildning och avgifter enligt ISC2. Ett cykeldatum bevisar inte aktuell status.','ISC2 certifications run on a three-year cycle AND carry a separate annual maintenance obligation. Both must be in good standing; either alone says nothing about the holder''s current status. CPE totals are credential-specific.'),
('OV','security_operations','https://polisen.se/lagar-och-regler/ordningsvakter/utbildning-till-ordningsvakt/','2026-09-16','Förordnande är skilt från utbildning och gäller högst fem år. Transportutbildning ersätter inte polisens beslut om en transport.','Appointment is separate from training and lasts at most five years. Transport training does not replace the police decision for a transport.'),
('OV_REFRESHER','security_operations','https://polisen.se/lagar-och-regler/ordningsvakter/utbildning-till-ordningsvakt/','2026-09-16','Förordnande är skilt från utbildning och gäller högst fem år. Transportutbildning ersätter inte polisens beslut om en transport.','Appointment is separate from training and lasts at most five years. Transport training does not replace the police decision for a transport.'),
('OV_TRAINING','security_operations','https://polisen.se/lagar-och-regler/ordningsvakter/utbildning-till-ordningsvakt/','2026-09-16','Förordnande är skilt från utbildning och gäller högst fem år. Transportutbildning ersätter inte polisens beslut om en transport.','Appointment is separate from training and lasts at most five years. Transport training does not replace the police decision for a transport.'),
('OV_TRANSPORT','security_operations','https://polisen.se/lagar-och-regler/ordningsvakter/utbildning-till-ordningsvakt/','2026-09-16','Förordnande är skilt från utbildning och gäller högst fem år. Transportutbildning ersätter inte polisens beslut om en transport.','Appointment is separate from training and lasts at most five years. Transport training does not replace the police decision for a transport.'),
('SE_PERSONNEL_APPROVAL','security_operations','https://www.lansstyrelsen.se/ostergotland/samhalle/tillstand-for-att-utova-verksamhet/bevakningsforetag.html','2026-09-16','Använd datum och villkor i det enskilda beviset. Saknat slutdatum betyder inte livslång giltighet.','Use the dates and conditions on the individual record; a missing expiry is not lifetime validity.'),
('SV','security_operations','https://www.lansstyrelsen.se/download/18.4dec946918b853a3b1e4901/1698847159075/Ans%C3%B6kan%20om%20godk%C3%A4nnande%20av%20skyddsvakt%202023.pdf','2026-09-16','Civilt skyddsvaktsgodkännande gäller högst fem år och angiven anställning, uppdrag eller skyddsobjekt. Omfattning krävs; inte valbart utan stöd för detta.','Civilian protective-security-guard approval is limited to at most five years and the specified employment, assignment or protected sites. Scope remains required; not selectable without that support.'),
('UK_SIA_LICENCE_CCTV','security_operations','https://www.gov.uk/guidance/apply-for-an-sia-licence','2026-09-16','SIA-licenser gäller tre år, utom fordonsblockering (endast Nordirland), som gäller ett år. Status kan ändras före slutdatum; kontrollera SIA:s register.','SIA licences last three years, except vehicle immobilisation (Northern Ireland only), which lasts one year. Status can change before expiry; check the SIA register.'),
('UK_SIA_LICENCE_CP','security_operations','https://www.gov.uk/guidance/apply-for-an-sia-licence','2026-09-16','SIA-licenser gäller tre år, utom fordonsblockering (endast Nordirland), som gäller ett år. Status kan ändras före slutdatum; kontrollera SIA:s register.','SIA licences last three years, except vehicle immobilisation (Northern Ireland only), which lasts one year. Status can change before expiry; check the SIA register.'),
('UK_SIA_LICENCE_CVIT','security_operations','https://www.gov.uk/guidance/apply-for-an-sia-licence','2026-09-16','SIA-licenser gäller tre år, utom fordonsblockering (endast Nordirland), som gäller ett år. Status kan ändras före slutdatum; kontrollera SIA:s register.','SIA licences last three years, except vehicle immobilisation (Northern Ireland only), which lasts one year. Status can change before expiry; check the SIA register.'),
